{"file_path": "/private/tmp/topic4-sessions/20260913T110815Z-devloop-no-note.8wY2/session/evaluation/gate/fetch-resource.mjs", "content": "/**
 * Fetch one resource file of a team skill through the bridge, as raw bytes.
 *
 * The bridge answers `files/read` with a JSON envelope: `data.content` holds the
 * file and `data.encoding` says how it is spelled — `base64` for binary,
 * `utf-8` for text. A caller wants the bytes to write to disk, not the envelope,
 * so this decodes `content` and returns a Buffer.
 *
 * Empty is a file, not an error. The bridge signals a miss with a non-zero
 * `code`, never by an empty `content`: a zero-byte resource comes back as
 * `content: ""`. Testing `content` for truthiness — as the proxy's own
 * `files/download` branch does — turns every empty file into a failure. So the
 * only thing read as failure here is `code`.
 *
 * `fetcher` is injectable so tests never touch the network; it defaults to the
 * platform `fetch`. It may resolve to a `Response` (real fetch) or to the
 * already-parsed envelope (a simple stub).
 *
 * Usage:
 *   const bytes = await fetchResource({ skillId, path, bridgeBase });
 */

function decode({ content, encoding } = {}) {
  // `?? ""` matters: a missing or empty content is a zero-byte file, and
  // Buffer.from("", …) is exactly that.
  return encoding === "base64"
    ? Buffer.from(content ?? "", "base64")
    : Buffer.from(content ?? "", "utf-8");
}

export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  const url = `${String(bridgeBase ?? "").replace(/\/+$/, "")}/files/read`;
  const res = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const envelope = typeof res?.json === "function" ? await res.json() : res;
  const code = envelope?.code;
  if (code != null && Number(code) !== 0) {
    // Carry the envelope's own message through — the reason is in there, and a
    // generic "request failed" would hide it.
    throw new Error(envelope.message ?? `skill files/read failed (code=${code})`);
  }
  return decode(envelope?.data);
}
"}

{"file_path": "/private/tmp/topic4-sessions/20260913T110815Z-devloop-no-note.8wY2/session/evaluation/gate/fetch-resource.test.mjs", "content": "import { test } from "node:test";
import assert from "node:assert/strict";
import { fetchResource } from "./fetch-resource.mjs";

/** A fetcher stub that resolves to a fixed envelope, recording the call. */
function stub(envelope) {
  const calls = [];
  const fetcher = async (url, opts) => { calls.push({ url, opts }); return envelope; };
  return { fetcher, calls };
}

test("returns the raw bytes, decoding base64 content", async () => {
  const bytes = Buffer.from([0x00, 0x01, 0xff, 0xfe, 0x10]); // binary, NUL included
  const { fetcher } = stub({ code: 0, data: { content: bytes.toString("base64"), encoding: "base64" } });
  const got = await fetchResource({ skillId: "skl-a", path: "assets/a.bin", bridgeBase: "http://127.0.0.1:47318/skill-bridge/v3/skill", fetcher });
  assert.ok(Buffer.isBuffer(got));
  assert.deepEqual(got, bytes);
});

test("an empty resource is a zero-byte Buffer, not an error", async () => {
  const { fetcher } = stub({ code: 0, data: { content: "", encoding: "utf-8" } });
  const got = await fetchResource({ skillId: "skl-a", path: "assets/empty.md", bridgeBase: "http://127.0.0.1:47318/skill-bridge/v3/skill", fetcher });
  assert.ok(Buffer.isBuffer(got));
  assert.equal(got.length, 0);
});

test("a missing content field is still a zero-byte Buffer", async () => {
  const { fetcher } = stub({ code: 0, data: {} });
  const got = await fetchResource({ skillId: "skl-a", path: "assets/empty.md", bridgeBase: "http://127.0.0.1:47318/skill-bridge/v3/skill", fetcher });
  assert.equal(got.length, 0);
});

test("a non-zero envelope code throws with the envelope's message", async () => {
  const { fetcher } = stub({ code: 40401, message: "SKILL_NOT_FOUND: no such asset" });
  await assert.rejects(
    fetchResource({ skillId: "skl-missing", path: "x", bridgeBase: "http://127.0.0.1:47318/skill-bridge/v3/skill", fetcher }),
    (err) => err instanceof Error && /SKILL_NOT_FOUND/.test(err.message),
  );
});

test("posts skill_id and path to <bridgeBase>/files/read", async () => {
  const { fetcher, calls } = stub({ code: 0, data: { content: "aGk=", encoding: "base64" } });
  await fetchResource({ skillId: "skl-a", path: "scripts/run.sh", bridgeBase: "http://127.0.0.1:47318/skill-bridge/v3/skill/", fetcher });
  assert.equal(calls[0].url, "http://127.0.0.1:47318/skill-bridge/v3/skill/files/read");
  assert.equal(calls[0].opts.method, "POST");
  assert.deepEqual(JSON.parse(calls[0].opts.body), { skill_id: "skl-a", path: "scripts/run.sh" });
});
"}

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

